const orig = await import('./orig.js');
const nw = await import('./new.js');

function rnd(n){return Math.floor(Math.random()*n);}
const events=[];
function makeInput(){
  const stock={}; const evs=[];
  if (rnd(3)===0) return null;
  const nStock=1+rnd(3);
  for(let i=0;i<nStock;i++) stock['it'+(1+rnd(4))]=rnd(8);
  // build a coherent sequence
  for(let k=0;k<200;k++){
    const t=rnd(6); const id='o'+rnd(6);
    if(t===0) evs.push({type:'order',id,item:'it'+(1+rnd(4)),qty:1+rnd(5)});
    else if(t===1) evs.push({type:'cancel',id});
    else if(t===2) evs.push({type:'ship',... (rnd(2)===0?{qty:1+rnd(5)}:{}) ,id});
    else if(t===3) evs.push({type:'restock',item:'it'+(1+rnd(4)),qty:1+rnd(5)});
    else if(t===4) evs.push({type:'expire',id});
    else evs.push({type:'ship',id});
    // sometimes corrupt
    if(rnd(20)===0) evs[evs.length-1]={type:'order'};
  }
  return {stock,events:evs};
}

function norm(r){
  const st={...r}; 
  if(st.stock){st.stock={...st.stock};}
  if(st.orders){st.orders={...st.orders};}
  if(st.queue){st.queue=[...st.queue];}
  return JSON.stringify(st);
}

let fails=0;
for(let i=0;i<20000;i++){
  const inp=makeInput();
  let a,b;
  try{a=orig.processEvents(inp);}catch(e){a='THROW '+e.message;}
  try{b=nw.processEvents(inp);}catch(e){b='THROW '+e.message;}
